<?php
namespace Tests\Feature;
use App\Http\Controllers\{AdminUnlockController,PartnerUnlockController}; use App\Models\{JpHold,Partner,RewardTransaction,Unlock,UnlockParticipation,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use ReflectionMethod; use Tests\TestCase;
class UnlockMetricsTest extends TestCase {use RefreshDatabase;
 public function test_admin_metrics_are_domain_derived_and_zero_safe():void{$x=$this->unlock();foreach(['INTERESTED','COMMITTED','CONFIRMED','FULFILLED','CANCELLED_ON_TIME','EXPIRED','NO_SHOW']as$s)UnlockParticipation::create(['unlock_id'=>$x->id,'user_id'=>User::factory()->create()->id,'status'=>$s]);$p=UnlockParticipation::where('unlock_id',$x->id)->where('status','FULFILLED')->first();JpHold::create(['user_id'=>$p->user_id,'unlock_participation_id'=>$p->id,'amount'=>5,'status'=>'RELEASED','held_at'=>now(),'released_at'=>now()]);RewardTransaction::create(['beneficiary_user_id'=>$p->user_id,'beneficiary_type'=>'USER','beneficiary_id'=>$p->user_id,'unlock_participation_id'=>$p->id,'reward_type'=>'JP','amount'=>3,'status'=>'available','source'=>'unlock_fulfillment']);$m=$this->metric(AdminUnlockController::class,$x);$this->assertSame(1,$m['interested']);$this->assertSame(4,$m['committed']);$this->assertSame(1,$m['confirmed']);$this->assertSame(1,$m['fulfilled']);$this->assertSame(1,$m['cancelled']);$this->assertSame(1,$m['expired']);$this->assertSame(1,$m['no_show']);$this->assertSame(5,$m['jp_released']);$this->assertSame(3,$m['jp_bonus_awarded']);$this->assertSame(25.0,$m['fulfillment_rate']);$this->assertSame(0,$this->metric(AdminUnlockController::class,$this->unlock())['fulfillment_rate']);}
 public function test_partner_metrics_and_rate_are_scoped():void{$a=$this->partner();$b=$this->partner();$x=$this->unlock(['partner_id'=>$a->id]);$this->unlock(['partner_id'=>$b->id]);foreach(['COMMITTED','FULFILLED','CANCELLED_ON_TIME','NO_SHOW']as$s)UnlockParticipation::create(['unlock_id'=>$x->id,'user_id'=>User::factory()->create()->id,'status'=>$s]);$m=$this->metric(PartnerUnlockController::class,$x);$this->assertSame(3,$m['committed']);$this->assertSame(1,$m['fulfilled']);$this->assertSame(1,$m['cancelled']);$this->assertSame(1,$m['no_show']);$this->assertSame(33.3,$m['fulfillment_rate']);}
 private function metric(string$c,Unlock$u):array{$r=new ReflectionMethod($c,'metrics');$r->setAccessible(true);return$r->invoke(app($c),$u);}private function partner():Partner{return Partner::create(['name'=>'P'.uniqid(),'slug'=>'p'.uniqid(),'entity_type'=>'BUSINESS','partner_type'=>'OTHER','status'=>'published']);}private function unlock(array$o=[]):Unlock{return Unlock::create(array_merge(['title'=>'U'.uniqid(),'slug'=>'u'.uniqid(),'origin'=>'JAKAWI','type'=>'EXPERIENCE','minimum_commitments'=>1,'free_user_eligible'=>true,'member_eligible'=>true,'jp_deposit'=>0,'jp_completion_bonus'=>0,'status'=>Unlock::UNLOCKED],$o));}}
